export function groupBy(items, key) {
  const result = {};
  for (const item of items) {
    const group = item[key];
    if (!Object.prototype.hasOwnProperty.call(result, group)) {
      // defineProperty avoids triggering the __proto__ setter for that key
      Object.defineProperty(result, group, {
        value: [],
        enumerable: true,
        writable: true,
        configurable: true,
      });
    }
    result[group].push(item);
  }
  return result;
}
