export function compareSemver(a, b) {
  const pa = parse(a);
  const pb = parse(b);
  for (let i = 0; i < 3; i++) {
    const c = compareDigits(pa[i], pb[i]);
    if (c !== 0) return c;
  }
  return 0;
}

function parse(version) {
  if (typeof version !== 'string') {
    throw new TypeError(`Invalid version: ${String(version)}`);
  }
  const match = /^(\d+)\.(\d+)\.(\d+)$/.exec(version);
  if (!match) {
    throw new TypeError(`Invalid version: ${version}`);
  }
  return [match[1], match[2], match[3]];
}

// Compares two non-negative integer strings numerically, without precision loss.
function compareDigits(x, y) {
  const nx = x.replace(/^0+(?=\d)/, '');
  const ny = y.replace(/^0+(?=\d)/, '');
  if (nx.length !== ny.length) return nx.length < ny.length ? -1 : 1;
  if (nx === ny) return 0;
  return nx < ny ? -1 : 1;
}
